"""Deterministic fixture readers against independent gold values (generated bytes only)."""

from __future__ import annotations

import hashlib
import io
import zipfile
from dataclasses import replace

import mixed_intake_fixture as fx
import pytest
from opentour_cell.pilot.mixed_intake import readers
from opentour_cell.pilot.mixed_intake.model import Deadline, ExtractionState, Limits

LIMITS = Limits()


def read(data: bytes, name: str, limits: Limits = LIMITS, **kw: bool):
    return readers.read_object(data, name, limits, Deadline(30.0), **kw)


def by_locator(result, **want):
    return [s for s in result.spans if all(s.locator.get(k) == v for k, v in want.items())]


